// Usage: node benchmarks/eval/free-directions.mjs [--json] [options-json]; needs target/release/layout-command.
// Free directions (`auto`) against a fixed one on the layered playground examples (generated by benchmarks/generate.py,
// deterministic): every area of the graph gets `auto` (or `lr`), nothing else changes. Prints per dataset and variant:
// width × height, aspect, area (M), crossings, bends, lines through nodes, single-pass edges built and delegated, ms.
// The optional argument adds layout options to every run (for an experimental option).
import {readFileSync, readdirSync} from 'node:fs';
import {arqlet, normalizeArqlet, metrics, round, ROOT} from './lib.mjs';

const dir = `${ROOT}apps/playground/generated/examples/`;
const extra = JSON.parse(process.argv.slice(2).find(a => a.startsWith('{')) ?? '{}');
// Layered only: graphs with other strategies do not use single pass at all yet.
const layeredOnly = g => !Object.values(g.containerStrategies ?? {}).some(s => s && s !== 'none')
  && (!g.defaultStrategy || g.defaultStrategy === 'none');

function directed(g, direction) {
  const containers = new Set(g.nodes.map(n => n.parentId).filter(Boolean));
  return {...g, defaultDirection: direction, containerDirections: Object.fromEntries([...containers].map(id => [id, direction]))};
}

const rows = [];
for (const file of readdirSync(dir).filter(f => f.endsWith('.json') && f !== 'index.json').sort()) {
  const raw = JSON.parse(readFileSync(dir + file, 'utf8'));
  const g = raw.graph ?? raw;
  if (!g.nodes || g.children || !layeredOnly(g) || g.nodes.length > 1500) continue;
  for (const direction of ['lr', 'auto']) {
    const {snapshot, ms} = arqlet({op: 'import', graph: directed(g, direction), limit: g.nodes.length, options: extra});
    const m = metrics(normalizeArqlet(snapshot));
    const sp = (snapshot.layoutDiagnostics ?? []).find(d => d.startsWith('Single pass:'));
    const built = sp ? Number(/(\d+) constructed/.exec(sp)[1]) : null;
    const delegated = sp ? Number(/(\d+) delegated/.exec(sp)[1]) : null;
    rows.push({dataset: file.replace('.json', ''), direction, nodes: g.nodes.length, edges: g.edges.length,
      width: round(m.width), height: round(m.height), aspect: round(m.width / m.height), areaM: round(m.area / 1e6),
      crossings: m.crossings, bends: m.bends, lineNodeHits: m.lineNodeHits, built, delegated, ms: Math.round(ms)});
  }
}
if (process.argv.includes('--json')) {
  for (const r of rows) console.log(JSON.stringify(r));
} else {
  console.log('| dataset | direction | nodes | width × height | aspect | area (M) | crossings | bends | line–node hits | single pass built / delegated | ms |');
  console.log('|---|---|---|---|---|---|---|---|---|---|---|');
  for (const r of rows) {
    console.log(`| ${r.dataset} | ${r.direction} | ${r.nodes} | ${r.width} × ${r.height} | ${r.aspect} | ${r.areaM} | ${r.crossings} | ${r.bends} | ${r.lineNodeHits} | ${r.built ?? '–'} / ${r.delegated ?? '–'} | ${r.ms} |`);
  }
}
